const CardSection=defineComponent({props:{code:String,title:String,subtitle:String,items:Array,icon:[Object,Function]},setup(props){return()=>{const items=props.items||[],isEmpty=value=>value===null||value===undefined||value===''||value==='—',filled=items.filter(([,value])=>!isEmpty(value)).length;return h('section',{class:['card-section','profile-data-section',`section-${props.code}`],id:`card-${props.code}`},[h(SectionTitle,{code:props.code,title:props.title,subtitle:props.subtitle}),h('div',{class:'section-completeness'},[h('div',{class:'section-completeness-icon'},props.icon?[h(props.icon,{size:22})]:[]),h('div',{class:'section-completeness-copy'},[h('b',`${props.code} 区资料概览`),h('span',filled===items.length?'本区字段已完整录入':`尚有 ${items.length-filled} 项字段待补充`)]),h('div',{class:['section-completeness-count',{complete:filled===items.length}]},[h('strong',String(filled)),h('span',`/ ${items.length}`),h('small','已录入')])]),h('div',{class:'card-grid'},items.map(([label,value])=>{const missing=isEmpty(value),display=missing?'未录入':String(value),wide=/详细地址/.test(label)||display.length>24;return h('div',{class:['card-cell',{missing,wide}]},[h('b',label),h('span',{title:missing?'待补充':display},display)])}))])}}})
const props=defineProps({mode:{type:String,default:'summary'}})
const route=useRoute(),router=useRouter(),auth=useAuthStore(),loading=ref(false),loadError=ref(''),uploading=ref(false),generatingPdf=ref(false),deletingPhotoId=ref(null),uploadDialog=ref(false),uploadFiles=ref([]),photoDescription=ref(''),uploadCategory=ref('overall'),photoIndex=reactive({}),previewUrl=ref(''),activeSection=ref('A'),selectedPeriodicCode=ref(''),data=ref({bridge:null,components:[],archives:[],evaluations:[],attachments:[],structureDetails:{spans:[],structures:[],cables:[]},inspectionSummary:{},initialInspections:[],initialItems:[],initialComponentItems:[],periodicInspections:[]})
const photoTypes=[{code:'overall',name:'桥梁总体照片'},{code:'front',name:'桥梁正面照片'},{code:'left_elevation',name:'桥梁左侧立面照片'},{code:'right_elevation',name:'桥梁右侧立面照片'},{code:'deck',name:'桥面照片'},{code:'pier_foundation',name:'桥墩及基础照片'},{code:'other',name:'其他桥梁照片'}]
const bridge=computed(()=>data.value.bridge),canUpload=computed(()=>['admin','engineer','inspector'].includes(auth.role)),canEdit=computed(()=>['admin','engineer'].includes(auth.role)),canGenerate=canEdit,show=(value,suffix='')=>value===null||value===undefined||value===''?'未录入':`${value}${suffix}`
const activeCard=computed(()=>props.mode==='summary'?'S':props.mode)
const cardSections=[{code:'A',name:'行政区划'},{code:'B',name:'行政识别'},{code:'C',name:'技术指标'},{code:'D',name:'结构信息'},{code:'E',name:'档案资料'},{code:'F',name:'检测评定'},{code:'H',name:'说明事项'},{code:'I',name:'桥梁照片'}]
