const dynamicDimensions=computed(()=>[{name:'桥面高程测点',count:data.value.structureDetails.measurementPoints?.length||0},{name:'桥梁分孔',count:data.value.structureDetails.spans?.length||0},{name:'结构体系',count:data.value.structureDetails.structures?.filter(x=>x.structure_type==='结构体系').length||0},{name:'斜拉索',count:data.value.structureDetails.cables?.filter(x=>x.cable_type==='斜拉索').length||0},{name:'吊杆',count:data.value.structureDetails.cables?.filter(x=>x.cable_type==='吊杆').length||0},{name:'系杆',count:data.value.structureDetails.cables?.filter(x=>x.cable_type==='系杆').length||0},{name:'桥台',count:data.value.structureDetails.structures?.filter(x=>x.structure_type==='桥台').length||0},{name:'桥墩',count:data.value.structureDetails.structures?.filter(x=>x.structure_type==='桥墩').length||0},{name:'支座',count:data.value.structureDetails.structures?.filter(x=>x.structure_type==='支座').length||0}])
const missingDynamicDimensions=computed(()=>dynamicDimensions.value.filter(item=>!item.count).map(item=>item.name))
const identityItems=computed(()=>[['路线编号',bridge.value.route_code],['路线名称',bridge.value.route_name],['路线等级',bridge.value.route_grade],['桥梁编号',bridge.value.bridge_code],['桥梁名称',bridge.value.bridge_name],['桥位桩号',bridge.value.pile_number],['功能类型',bridge.value.function_type],['被跨越道路（通道）名称',bridge.value.crossed_road_name],['被跨越道路（通道）桩号',bridge.value.crossed_road_pile],['设计荷载',bridge.value.design_load],['桥梁坡度',bridge.value.bridge_slope],['桥梁平曲线半径',bridge.value.curve_radius],['建成年份',bridge.value.built_year],['设计单位',bridge.value.design_unit],['施工单位',bridge.value.construction_unit],['监理单位',bridge.value.supervision_unit],['业主单位',bridge.value.owner_unit],['管养单位',bridge.value.management_unit]])
const technicalItems=computed(()=>[['桥梁全长（m）',bridge.value.bridge_length],['桥面总宽（m）',bridge.value.deck_width],['车道宽度（m）',bridge.value.lane_width],['人行道宽度（m）',bridge.value.sidewalk_width],['护栏或防撞墙高度（m）',bridge.value.barrier_height],['中央分隔带宽度（m）',bridge.value.median_width],['桥面标准净空',bridge.value.standard_clearance],['桥面实际净空',bridge.value.actual_clearance],['桥下通航等级及标准净空',bridge.value.navigation_standard],['桥下实际净空',bridge.value.navigation_actual],['引道总宽（m）',bridge.value.approach_width],['引道线形或曲线半径',bridge.value.approach_alignment],['设计洪水频率及其水位',bridge.value.design_flood],['历史洪水位',bridge.value.historical_flood],['地震动峰值加速度系数',bridge.value.seismic_coefficient]])
const sortedEvaluations=computed(()=>[...data.value.evaluations].sort((a,b)=>{const dateCompare=String(a.evaluation_date||'9999-12-31').localeCompare(String(b.evaluation_date||'9999-12-31'));if(dateCompare)return dateCompare;const order=x=>/初始/.test(x.check_category_name||'')?0:1;return order(a)-order(b)}))
function printCard(){window.print()}
function goCard(card){const base=`/bridges/${encodeURIComponent(bridge.value.bridge_code)}`;router.push(card==='S'?base:`${base}/${card}`)}
