async function generateCardPdf(){generatingPdf.value=true;try{const report=await http.post(`/reports/bridge-card/${bridge.value.bridge_code}`,{});await downloadReport(report);ElMessage.success('桥梁基本状况卡片 PDF 已生成')}finally{generatingPdf.value=false}}
async function generateInitialPdf(){generatingPdf.value=true;try{const report=await http.post(`/reports/bridge-card/${bridge.value.bridge_code}/initial`,{});await downloadReport(report);ElMessage.success('初始检查记录表 PDF 已生成')}finally{generatingPdf.value=false}}
async function generatePeriodicPdf(){if(!selectedPeriodicCode.value)return;generatingPdf.value=true;try{const report=await http.post(`/reports/bridge-card/${bridge.value.bridge_code}/periodic/${selectedPeriodicCode.value}`,{});await downloadReport(report);ElMessage.success('定期检查记录表 PDF 已生成')}finally{generatingPdf.value=false}}
async function generateSummaryPdf(){generatingPdf.value=true;try{const report=await http.post(`/reports/bridge-card/${bridge.value.bridge_code}/summary`,{});await downloadReport(report);ElMessage.success('检查趋势与对比 PDF 已生成')}finally{generatingPdf.value=false}}
async function downloadReport(report){const response=await fetch(`/api/reports/${report.report_id}/download`,{headers:{Authorization:`Bearer ${localStorage.getItem('bridge_token')}`}});if(!response.ok)throw new Error('PDF 下载失败');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`${report.report_id}.pdf`;link.click();URL.revokeObjectURL(url)}
let sectionObserver
function observeSections(){sectionObserver?.disconnect();if(activeCard.value!=='A')return;sectionObserver=new IntersectionObserver(entries=>{const visible=entries.filter(x=>x.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(visible)activeSection.value=visible.target.id.replace('card-','')},{rootMargin:'-120px 0px -62% 0px',threshold:[.05,.25,.6]});cardSections.forEach(({code})=>{const element=document.querySelector(`#card-${code}`);if(element)sectionObserver.observe(element)})}
async function load(){loading.value=true;loadError.value='';data.value={bridge:null,components:[],archives:[],evaluations:[],attachments:[],structureDetails:{spans:[],structures:[],cables:[]},inspectionSummary:{},initialInspections:[],initialItems:[],initialComponentItems:[],periodicInspections:[]};try{data.value=await http.get(`/bridge-profiles/${route.params.bridgeCode}`);await nextTick();observeSections()}catch(error){loadError.value=error?.message||'桥梁档案加载失败'}finally{loading.value=false}}
async function submitPhotos(){uploading.value=true;try{for(const item of uploadFiles.value){if(!item.raw)continue;if(item.raw.size>10*1024*1024)throw new Error(`${item.name} 超过10MB`);const form=new FormData();form.append('file',item.raw);form.append('description',photoDescription.value);form.append('category',uploadCategory.value);await http.post(`/bridge-profiles/${bridge.value.bridge_code}/photos`,form)}ElMessage.success('桥梁照片上传成功');uploadFiles.value=[];uploadDialog.value=false;await load()}catch(error){ElMessage.error(error.message||'照片上传失败')}finally{uploading.value=false}}
async function removePhoto(file){if(!file)return;deletingPhotoId.value=file.file_id;try{await http.delete(`/bridge-profiles/${bridge.value.bridge_code}/photos/${file.file_id}`);const idx=data.value.attachments.findIndex(a=>a.file_id===file.file_id);if(idx>=0)data.value.attachments.splice(idx,1);ElMessage.success('照片已删除')}catch(error){ElMessage.error(error.message||'照片删除失败')}finally{deletingPhotoId.value=null}}
onMounted(load)
watch(()=>props.mode,async()=>{await nextTick();observeSections()})
onBeforeUnmount(()=>sectionObserver?.disconnect())
</script>

